#!/usr/bin/env python3
"""Batch 27: the last four -- #83 #88 #118 #220.

  #83   "the NCorp corpora were generated by NCorp different models" does
        not say whose design that is.  Both the corpora and the generators
        are Ref.~[1]'s.
  #88   The "autoregressive (AR) ladder" abbreviation is introduced in the
        abstract and nowhere in the body, so a reader who starts at
        Section 3 meets "AR ladder" undefined.  Section 3.1 introduces it
        where the evaluators are listed.
  #118  "for the reason Section 6.3 gives about its own" sends the reader
        forward for something Section 5.3 can say in place: the corpus is
        the independent unit, not the cell.
  #220  Table 10's caption says sigEP vanishes "independently of the loss
        column beside it", which invites a comparison down that column
        that the two rows do not admit: they are losses of two different
        objectives.

Idempotent.  Run from the directory holding main.tex.

    python3 -I fix_apply_b27.py [--dry-run]
"""

import argparse
import os
import sys

EDITS = [
    # ---- #88 ---------------------------------------------------------------
    ("main.tex",
     "Four of the five autoregressive evaluators differ in parameter count within one\n"
     "family, the four \\textsc{gpt-2} rungs,",
     "The five autoregressive evaluators, ordered by parameter count, are what\n"
     "this paper calls the \\emph{autoregressive (AR) ladder}, and a \\emph{rung}\n"
     "of it is one of them.  Four of the five differ in parameter count within one\n"
     "family, the four \\textsc{gpt-2} rungs,",
     "88 main:695"),

    # ---- #83 ---------------------------------------------------------------
    ("main.tex",
     "First, the $\\NCorp$ corpora were generated by $\\NCorp$ different models,\n"
     "though not by $\\NCorp$ independent lineages:",
     "First, the $\\NCorp$ corpora, and the $\\NCorp$ models that generated them,\n"
     "are Ref.~\\cite{sagawa2026}'s~\\cite[Sec.~V~B]{sagawa2026}; we re-score them\n"
     "and did not design them.  They are $\\NCorp$ different models, though not\n"
     "$\\NCorp$ independent lineages:",
     "83 main:1196"),

    # ---- #118 --------------------------------------------------------------
    ("sec_decomp.tex",
     "so they are not \\TailNCells\\ independent draws, for the\n"
     "reason Section~\\ref{sec:fbresult} gives about its own.",
     "so they are not \\TailNCells\\ independent draws: the\n"
     "independent unit here is the corpus, not the cell.",
     "118 decomp:152"),

    # ---- #220 --------------------------------------------------------------
    ("main.tex",
     "reversible and $\\sigEP$ vanishes identically, independently of the loss column\n"
     "beside it;",
     "reversible and $\\sigEP$ vanishes identically, whatever the loss it reaches;\n"
     "the \\emph{loss} column is not comparable between the two rows, the two\n"
     "objectives differing in what they condition on;",
     "220 tab:capacity caption"),
]

FILES = sorted({e[0] for e in EDITS})


def apply_edits(root, dry_run=False):
    cache = {}
    for name in FILES:
        with open(os.path.join(root, name), encoding="utf-8") as fh:
            cache[name] = fh.read()
    made = skipped = passed = 0
    for edit in EDITS:
        name, old, new, label = edit[:4]
        later = edit[4] if len(edit) > 4 else None
        text = cache[name]
        done = (new in text) if old in new else (old not in text and new in text)
        if done:
            print(f"  skip  {label:<26} already applied")
            skipped += 1
            continue
        n = text.count(old)
        if n != 1:
            if later and old not in text:
                print(f"  pass  {label:<26} superseded by {later}")
                passed += 1
                continue
            print(f"  MISS  {label:<26} target occurs {n} times in {name}")
            return None
        cache[name] = text.replace(old, new, 1)
        print(f"  apply {label:<26} {name}")
        made += 1
    if not dry_run:
        for name, text in cache.items():
            with open(os.path.join(root, name), "w", encoding="utf-8") as fh:
                fh.write(text)
    return made, skipped, passed


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".")
    ap.add_argument("--dry-run", action="store_true")
    args = ap.parse_args()
    print("batch 27: #83 #88 #118 #220")
    print("-" * 52)
    result = apply_edits(args.root, args.dry_run)
    if result is None:
        print("-" * 52)
        print("FAIL  nothing written.")
        return 1
    made, skipped, passed = result
    print("-" * 52)
    print(f"{'DRY RUN  ' if args.dry_run else ''}{made} applied, "
          f"{skipped} already in place"
          + (f", {passed} superseded later." if passed else "."))
    return 0


if __name__ == "__main__":
    sys.exit(main())
